// Package nonce implements an encrypted nonce service for ACME protocol.
//
// Nonces are generated by encrypting a monotonically increasing counter using
// AES-GCM. To redeem a nonce, the service decrypts it and verifies:
// 1. The counter is between earliest and latest valid values
// 2. The counter hasn't been used before (cross-off list)
//
// The cross-off list is managed using a map for O(1) lookup and a min-heap
// for efficient retirement of oldest nonces. When maxUsed is exceeded,
// the oldest nonce is retired and earliest is updated.
package nonce

import (
	"container/heap"
	"crypto/aes"
	"crypto/cipher"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"math/big"
	"sync"
	"sync/atomic"

	"github.com/jeremyhahn/go-xkms/pkg/acme/errors"
)

const (
	// PrefixLen is the length of a nonce prefix in characters.
	PrefixLen = 8

	// NonceLen is the length of a nonce body (excluding prefix) in bytes.
	NonceLen = 32

	// DefaultMaxUsed is the default maximum number of used nonces to track.
	DefaultMaxUsed = 65536

	// NonceSize is the AES-GCM nonce size.
	nonceSize = 12

	// KeySize is the AES key size.
	keySize = 16
)

// int64Heap is a min-heap of int64 values for efficient oldest-nonce finding.
type int64Heap []int64

func (h int64Heap) Len() int           { return len(h) }
func (h int64Heap) Less(i, j int) bool { return h[i] < h[j] }
func (h int64Heap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *int64Heap) Push(x any) {
	*h = append(*h, x.(int64))
}

func (h *int64Heap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

// Service generates, validates, and tracks nonces.
type Service struct {
	mu       sync.Mutex
	latest   atomic.Int64
	earliest int64
	used     map[int64]bool
	usedHeap *int64Heap
	gcm      cipher.AEAD
	maxUsed  int
	prefix   string
}

// Option configures a Service.
type Option func(*Service) error

// WithMaxUsed sets the maximum number of used nonces to track.
func WithMaxUsed(max int) Option {
	return func(s *Service) error {
		if max <= 0 {
			s.maxUsed = DefaultMaxUsed
		} else {
			s.maxUsed = max
		}
		return nil
	}
}

// WithPrefix sets the nonce prefix.
// The prefix must be 8 characters of valid base64url encoding.
func WithPrefix(prefix string) Option {
	return func(s *Service) error {
		if prefix == "" {
			return nil
		}
		if len(prefix) != PrefixLen {
			return errors.NewValidationError("prefix", "must be 8 characters", prefix)
		}
		if _, err := base64.RawURLEncoding.DecodeString(prefix); err != nil {
			return errors.NewValidationError("prefix", "must be valid base64url", prefix)
		}
		s.prefix = prefix
		return nil
	}
}

// WithKey sets a specific encryption key (for testing or key persistence).
func WithKey(key []byte) Option {
	return func(s *Service) error {
		if len(key) != keySize {
			return errors.NewValidationError("key", "must be 16 bytes", nil)
		}
		c, err := aes.NewCipher(key)
		if err != nil {
			return err
		}
		gcm, err := cipher.NewGCM(c)
		if err != nil {
			return err
		}
		s.gcm = gcm
		return nil
	}
}

// NewService creates a new nonce service.
func NewService(opts ...Option) (*Service, error) {
	s := &Service{
		used:     make(map[int64]bool, DefaultMaxUsed),
		usedHeap: &int64Heap{},
		maxUsed:  DefaultMaxUsed,
	}

	for _, opt := range opts {
		if err := opt(s); err != nil {
			return nil, err
		}
	}

	// Generate random key if not provided.
	if s.gcm == nil {
		key := make([]byte, keySize)
		if _, err := rand.Read(key); err != nil {
			return nil, err
		}
		c, err := aes.NewCipher(key)
		if err != nil {
			return nil, err
		}
		gcm, err := cipher.NewGCM(c)
		if err != nil {
			return nil, err
		}
		s.gcm = gcm
	}

	heap.Init(s.usedHeap)
	return s, nil
}

// DerivePrefix derives a nonce prefix from an address and key using HMAC-SHA256.
// This allows multiple nonce services to have unique, deterministic prefixes.
func DerivePrefix(addr string, key []byte) string {
	h := hmac.New(sha256.New, key)
	h.Write([]byte(addr))
	return base64.RawURLEncoding.EncodeToString(h.Sum(nil))[:PrefixLen]
}

// Generate creates a new unique nonce.
func (s *Service) Generate() (string, error) {
	counter := s.latest.Add(1)
	return s.encrypt(counter)
}

// Redeem validates and marks a nonce as used.
// Returns nil if valid, or an error describing why the nonce is invalid.
func (s *Service) Redeem(nonce string) error {
	counter, err := s.decrypt(nonce)
	if err != nil {
		return errors.NewNonceError("unable to decrypt nonce", err)
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	latest := s.latest.Load()

	// Check if nonce is too high (not yet issued).
	if counter > latest {
		return errors.NewNonceError("nonce greater than highest dispensed", errors.ErrNonceTooHigh)
	}

	// Check if nonce is too old.
	if counter <= s.earliest {
		return errors.NewNonceError("nonce less than lowest eligible", errors.ErrNonceTooLow)
	}

	// Check if nonce was already used.
	if s.used[counter] {
		return errors.NewNonceError("nonce already redeemed", errors.ErrNonceAlreadyUsed)
	}

	// Mark as used.
	s.used[counter] = true
	heap.Push(s.usedHeap, counter)

	// Retire oldest if we exceed maxUsed.
	if len(s.used) > s.maxUsed {
		oldest := heap.Pop(s.usedHeap).(int64)
		s.earliest = oldest
		delete(s.used, oldest)
	}

	return nil
}

// Valid checks if a nonce is valid without marking it as used.
func (s *Service) Valid(nonce string) error {
	counter, err := s.decrypt(nonce)
	if err != nil {
		return errors.NewNonceError("unable to decrypt nonce", err)
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	latest := s.latest.Load()

	if counter > latest {
		return errors.NewNonceError("nonce greater than highest dispensed", errors.ErrNonceTooHigh)
	}

	if counter <= s.earliest {
		return errors.NewNonceError("nonce less than lowest eligible", errors.ErrNonceTooLow)
	}

	if s.used[counter] {
		return errors.NewNonceError("nonce already redeemed", errors.ErrNonceAlreadyUsed)
	}

	return nil
}

// encrypt encrypts a counter value to produce a nonce.
func (s *Service) encrypt(counter int64) (string, error) {
	// Generate 12-byte nonce for AES-GCM:
	// - bytes 0-3: zero (deterministic prefix, not included in output)
	// - bytes 4-11: cryptographically random (8 bytes = 64 bits of randomness)
	// This provides sufficient uniqueness for the nonce space while allowing
	// the random portion to be included in the final nonce token.
	nonce := make([]byte, nonceSize)
	if _, err := rand.Read(nonce[4:]); err != nil {
		return "", err
	}

	// Encode counter to 8-byte big-endian.
	pt := make([]byte, 8)
	ctr := big.NewInt(counter)
	ctrBytes := ctr.Bytes()
	copy(pt[8-len(ctrBytes):], ctrBytes)

	// Encrypt with AES-GCM.
	// #nosec G407 - nonce bytes 4-11 are random (line above), bytes 0-3 are zero by design
	ct := s.gcm.Seal(nil, nonce, pt, nil)

	// Combine: random_nonce_bytes[4:] || ciphertext
	result := make([]byte, NonceLen)
	copy(result, nonce[4:])
	copy(result[8:], ct)

	return s.prefix + base64.RawURLEncoding.EncodeToString(result), nil
}

// decrypt decrypts a nonce to extract the counter value.
func (s *Service) decrypt(nonce string) (int64, error) {
	body := nonce

	// Handle prefix.
	if s.prefix != "" {
		if len(nonce) < PrefixLen {
			return 0, errors.ErrInvalidNonceLength
		}
		prefix := nonce[:PrefixLen]
		if prefix != s.prefix {
			return 0, errors.ErrNoncePrefixMismatch
		}
		body = nonce[PrefixLen:]
	}

	decoded, err := base64.RawURLEncoding.DecodeString(body)
	if err != nil {
		return 0, err
	}
	if len(decoded) != NonceLen {
		return 0, errors.ErrInvalidNonceLength
	}

	// Reconstruct AES-GCM nonce.
	n := make([]byte, nonceSize)
	copy(n[4:], decoded[:8])

	// Decrypt.
	pt, err := s.gcm.Open(nil, n, decoded[8:], nil)
	if err != nil {
		return 0, err
	}

	// Decode counter.
	ctr := new(big.Int)
	ctr.SetBytes(pt)
	return ctr.Int64(), nil
}

// Prefix returns the nonce prefix.
func (s *Service) Prefix() string {
	return s.prefix
}

// Latest returns the most recently issued counter value.
func (s *Service) Latest() int64 {
	return s.latest.Load()
}

// Earliest returns the earliest valid counter value.
func (s *Service) Earliest() int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.earliest
}

// UsedCount returns the number of used nonces being tracked.
func (s *Service) UsedCount() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.used)
}
